package com.turboio.addon;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public final class DailySummaryTest {
 static int checks;static void yes(boolean v){checks++;if(!v)throw new AssertionError("Daily summary "+checks);}interface Work{void run()throws Exception;}static void rejects(Work r)throws Exception{checks++;try{r.run();}catch(IOException|IllegalArgumentException e){return;}throw new AssertionError("Expected rejection "+checks);}
 static Map<String,Object> row(){return WireJson.object("periodType","daily","periodStart","2026-10-26","periodEnd","2026-10-26","timezone","Asia/Shanghai","title","合成日报","context","合成 AI 总结","generatedAt","2026-10-26T08:00:00.000+08:00","originalList",Arrays.asList("NEVER_UPLOAD_TRANSCRIPT"),"audio","NEVER_UPLOAD_AUDIO","latitude",30);}
 static List<DailySummary> parse(Object...r){return DailySummary.latest(WireJson.bytes(WireJson.object("code",0,"data",Arrays.asList(r))));}
 public static void main(String[] args)throws Exception{Map<String,Object> row=row();List<DailySummary> summaries=parse(row);yes(summaries.size()==1);DailySummary summary=summaries.get(0);String account="a".repeat(64);String body=new String(WireJson.bytes(summary.body(account,1)),StandardCharsets.UTF_8);yes(body.contains("合成 AI 总结")&&!body.contains("NEVER_UPLOAD")&&!body.contains("latitude"));yes(summary.body(account,1).get("source").equals("agent_analysis"));yes(WireJson.list(summary.body(account,1).get("utterances")).isEmpty());yes(WireJson.map(summary.body(account,1).get("audio")).get("state").equals("not_retained"));yes(!summary.id(account).equals(summary.id("b".repeat(64))));
  rejects(()->parse(row,row));Map<String,Object> weekly=new HashMap<>(row);weekly.put("periodType","weekly");yes(parse(weekly).isEmpty());Map<String,Object> empty=new HashMap<>(row);empty.put("context","");yes(parse(empty).isEmpty());Map<String,Object> invalid=new HashMap<>(row);invalid.put("periodEnd","2026-10-27");rejects(()->parse(invalid));
  File root=new File(args[0]);root.mkdirs();MaterialConnection connection=LifelogImportJournalTest.connection(System.currentTimeMillis());MaterialConfig config=new MaterialConfig(connection,account,true);MaterialSyncSessionTest.MemoryServer server=new MaterialSyncSessionTest.MemoryServer(connection);Set<String> dates=Collections.singleton(summary.date);
  MaterialSyncSession.Status first=DailySummarySync.run(root,config,summaries,dates,()->{},server);yes(first.stored==1&&first.selectedComplete&&server.posts==1);yes(DailySummarySync.run(root,config,summaries,dates,()->{},server).added==0&&server.posts==1);
  Map<String,Object> changed=new HashMap<>(row);changed.put("context","更正后的合成 AI 总结");MaterialSyncSession.Status update=DailySummarySync.run(root,config,parse(changed),dates,()->{},server);yes(update.stored==1&&server.posts==2);try(MaterialOutbox queue=new MaterialOutbox(DailySummarySync.directory(root,config),connection)){yes(queue.all().size()==1&&queue.retiredCount()==1);Map<String,Object> r=WireJson.map(queue.all().get(0));Map<String,Object> e=MaterialWire.event(((String)r.get("payload")).getBytes(StandardCharsets.UTF_8),connection.producer);yes(MaterialWire.positive(WireJson.map(e.get("body")).get("revision"))==2);Files.write(Path.of(args[1]),WireJson.bytes(e));}
  rejects(()->DailySummarySync.run(root,config,summaries,Collections.singleton("2026-10-01"),()->{},server));yes(server.posts==2);rejects(()->DailySummarySync.run(root,config.enabled(false),summaries,dates,()->{},server));rejects(()->DailySummarySync.run(root,config,summaries,dates,()->{throw new IOException("ACCOUNT_CHANGED");},server));yes(server.posts==2);
  File retry=new File(root,"retry");server.drop=true;rejects(()->DailySummarySync.run(retry,config,summaries,dates,()->{},server));yes(DailySummarySync.status(retry,config).reconcile==1);try(MaterialOutbox queue=new MaterialOutbox(DailySummarySync.directory(retry,config),connection)){new MaterialApi(connection,server).pump(queue,System.currentTimeMillis()+60000);}yes(DailySummarySync.run(retry,config,summaries,dates,()->{},server).stored==1&&server.lookups==1);
  File old=MaterialStorage.prepare(root,config);try(MaterialOutbox legacy=new MaterialOutbox(old,connection)){yes(legacy.all().isEmpty());}yes(!old.equals(DailySummarySync.directory(root,config)));yes(DailySummarySync.status(root,new MaterialConfig(connection,"b".repeat(64),true)).stored==0);
  long start=java.time.Instant.parse("2026-10-26T01:00:00Z").toEpochMilli();
  try(MaterialAutoSchedule oldSchedule=new MaterialAutoSchedule(root,config)){MaterialAutoSchedule.Plan plan=oldSchedule.begin(start,"Asia/Shanghai",false);oldSchedule.finish(plan,start,true);}
  try(MaterialAutoSchedule recent=new MaterialAutoSchedule(root,config,true)){MaterialAutoSchedule.Plan plan=recent.begin(start+1000,"Asia/Shanghai",false);yes(plan!=null);recent.finish(plan,start+1000,true);yes(recent.begin(start+2000,"Asia/Shanghai",false)==null);}
  try(MaterialAutoSchedule recent=new MaterialAutoSchedule(root,config,true)){MaterialAutoSchedule.Plan plan=recent.begin(start+10*86400000L,"Asia/Shanghai",false);yes(plan.days.get(1).date.equals("2026-11-04"));}
  System.out.println("Daily summary: "+checks+" checks passed");
 }
}
